const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');const{fixture,scalar}=require('./harness.cjs');
async function totals(db){return(await db.query('select *from private.provider_snapshot_storage_usage order by storage_class')).rows;}
async function checkCounters(db){const actual=await totals(db);const expected=(await db.query(`select c.storage_class,coalesce(j.jobs,0)jobs,coalesce(j.failed_jobs,0)failed_jobs,coalesce(a.artifacts,0)artifacts,coalesce(a.stored_bytes,0)stored_bytes from(values('hot'),('history'))c(storage_class)
 left join(select private.provider_snapshot_storage_class(target,window_from,window_to)storage_class,count(*)jobs,count(*)filter(where status='failed')failed_jobs from private.provider_snapshot_jobs group by 1)j using(storage_class)
 left join(select private.provider_snapshot_storage_class(j.target,j.window_from,j.window_to)storage_class,count(*)artifacts,sum(a.stored_bytes)stored_bytes from private.provider_snapshot_artifacts a join private.provider_snapshot_jobs j on j.id=a.job_id group by 1)a using(storage_class)order by c.storage_class`)).rows;assert.deepEqual(actual,expected);}
async function readerSetup(db,targets){const owner='10000000-0000-4000-8000-000000000001';await db.query("insert into public.dashboard_profiles values($1,'owner',true,'{\"mode\":\"all\",\"countries\":[]}')",[owner]);await db.exec("insert into private.test_native_catalog select *from private.provider_snapshot_native_catalog()where source='ar'");await db.query("select set_config('test.actor',$1,false),set_config('test.session_allowed','true',false),set_config('test.ip_allowed','true',false)",[owner]);return async(day,end='23:59:59')=>scalar(db,'select public.dashboard_admin_provider_snapshot($1)',[JSON.stringify({version:1,platformIds:targets.map(t=>t.id),startAt:day+'T00:00:00',endAt:day+'T'+end,direction:'charge',status:'all',currency:'INR',components:['orders','submission','intake']})]);}
test('two budgets classify exact full local days, bootstrap existing metadata, and account retry/delete without payload decoding',async()=>{const{db,cohort,retire,gc}=await fixture();try{await cohort('2026-10-08',24,{lane:'closed'});const old=await cohort('2026-10-10',10);await cohort('2026-10-10',12);for(const f of['quota.sql','enqueue-after.sql','complete-after.sql','reader-after.sql','maintenance.sql'])await db.exec(fs.readFileSync(path.join(__dirname,f),'utf8'));await checkCounters(db);assert.deepEqual((await totals(db)).map(r=>[r.storage_class,Number(r.jobs),Number(r.artifacts)]),[['history',10,10],['hot',20,20]]);await db.query("update private.provider_snapshot_jobs set status='failed',attempts=3 where id=$1",[old.jobs[0]]);assert.equal((await retire(old.id)).status,'active_jobs_protected');await checkCounters(db);await db.query("update private.provider_snapshot_jobs set status='ready' where id=$1",[old.jobs[0]]);assert.equal((await retire(old.id)).status,'retired');await gc(200);await checkCounters(db);assert.deepEqual((await totals(db)).map(r=>[r.storage_class,Number(r.jobs)]),[['history',10],['hot',10]]);}finally{await db.close()}});
test('full hot job quota cannot consume history budget; existing key replay is accepted at quota',async()=>{const{db,cohort}=await fixture({tiered:true});try{await cohort('2026-10-10',10);const j=(await db.query("select target,request,component from private.provider_snapshot_jobs limit 1")).rows[0];await db.exec("update private.provider_snapshot_storage_usage set jobs=5000 where storage_class='hot'");assert.ok(await scalar(db,'select private.provider_snapshot_enqueue($1,$2,$3)',[j.target,j.request,j.component]));await db.exec('begin');await assert.rejects(()=>cohort('2026-10-10',11),/snapshot_queue_capacity/);await db.exec('rollback');await cohort('2026-10-11',24,{lane:'closed'});assert.equal(Number((await totals(db)).find(r=>r.storage_class==='history').jobs),10);await db.exec("update private.provider_snapshot_storage_usage set jobs=50000 where storage_class='history'");await assert.rejects(()=>cohort('2026-10-13',24,{lane:'closed'}),/snapshot_queue_capacity/);}finally{await db.close()}});
test('artifact number and byte caps stop publication atomically and preserve lastgood; classes remain independent',async()=>{const{db,cohort}=await fixture({tiered:true});try{const old=await cohort('2026-10-10',10);const id=old.jobs[0];const saved=(await db.query('select a.*,j.target,j.request,j.component from private.provider_snapshot_heads h join private.provider_snapshot_artifacts a on a.id=h.snapshot_id join private.provider_snapshot_jobs j on j.id=h.job_id where h.job_id=$1',[id])).rows[0];for(const column of['artifacts','stored_bytes']){await db.query('select private.provider_snapshot_requeue($1)',[id]);await db.query("update private.provider_snapshot_cohorts set status='building'where id=$1",[old.id]);const claim=await scalar(db,"select private.provider_snapshot_claim('quota',120)");await db.exec(`update private.provider_snapshot_storage_usage set ${column}=${column==='artifacts'?2048:268435456} where storage_class='hot'`);await assert.rejects(()=>scalar(db,'select private.provider_snapshot_complete($1,$2,$3,$4,$5)',[claim.jobId,claim.runId,claim.fence,saved.payload,saved.provenance]),/snapshot_artifact_capacity/);assert.equal(await scalar(db,'select snapshot_id::text from private.provider_snapshot_heads where job_id=$1',[id]),saved.id);await db.exec("update private.provider_snapshot_storage_usage set artifacts=10,stored_bytes=(select sum(stored_bytes)from private.provider_snapshot_artifacts)where storage_class='hot'");await db.query("update private.provider_snapshot_jobs set status='ready',lease_until=null where id=$1",[id]);}
await db.exec("update private.provider_snapshot_cohorts set status='ready';update private.provider_snapshot_storage_usage set artifacts=2048 where storage_class='hot'");await cohort('2026-10-12',24,{lane:'closed'});assert.equal(Number((await totals(db)).find(r=>r.storage_class==='history').artifacts),10);}finally{await db.close()}});
test('reader complete DTO stays identical after window prefilter; retired historical intraday returns missing, never a newer cutoff',async()=>{const{db,targets,cohort}=await fixture();try{const read=await readerSetup(db,targets);const old=await cohort('2026-10-10',10);await cohort('2026-10-10',12);await cohort('2026-10-01',24,{lane:'closed'});await cohort('2026-10-09',24,{lane:'closed'});const before=await read('2026-10-10'),daily=await read('2026-10-09');for(const f of['quota.sql','enqueue-after.sql','complete-after.sql','reader-after.sql','maintenance.sql'])await db.exec(fs.readFileSync(path.join(__dirname,f),'utf8'));assert.deepEqual(await read('2026-10-10'),before);assert.deepEqual(await read('2026-10-09'),daily);assert.equal((await read('2026-10-10','10:30:00')).status,'ready');const maintenance=await scalar(db,'select private.provider_snapshot_maintain(200)');assert.equal(maintenance.retirement.status,'retired');const missing=await read('2026-10-10','10:30:00');assert.equal(missing.status,'missing');assert.equal(missing.publishedCutoff,null);assert.equal((await read('2026-10-10')).publishedCutoff,before.publishedCutoff);assert.deepEqual(await read('2026-10-09'),daily);await checkCounters(db);await db.query("select set_config('test.ip_allowed','false',false)");await assert.rejects(()=>read('2026-10-10'),/application_session_denied/);}finally{await db.close()}});
test('identity edits cannot move occupied storage across budgets; browser roles cannot administer storage',async()=>{const{db,cohort}=await fixture({tiered:true});try{await cohort('2026-10-10',10);await assert.rejects(()=>db.exec("update private.provider_snapshot_jobs set window_to=window_from+interval'1day'"),/snapshot_job_identity_immutable/);await checkCounters(db);for(const role of['anon','authenticated','service_role']){assert.equal(await scalar(db,"select has_table_privilege($1,'private.provider_snapshot_storage_usage','SELECT')",[role]),false);assert.equal(await scalar(db,"select has_function_privilege($1,'private.provider_snapshot_maintain(integer)','EXECUTE')",[role]),false);}}finally{await db.close()}});
test('history artifact hard stops are independent and keep prior head/revision; failed jobs still admit terminal recording',async()=>{const{db,cohort}=await fixture({tiered:true});try{const c=await cohort('2026-10-10',24,{lane:'closed'}),id=c.jobs[0];const saved=(await db.query('select a.*from private.provider_snapshot_heads h join private.provider_snapshot_artifacts a on a.id=h.snapshot_id where h.job_id=$1',[id])).rows[0];for(const [column,limit]of[['artifacts',25000],['stored_bytes',2147483648]]){await db.query('select private.provider_snapshot_requeue($1)',[id]);await db.query("update private.provider_snapshot_cohorts set status='building'where id=$1",[c.id]);const claim=await scalar(db,"select private.provider_snapshot_claim('history-quota',120)");await db.query(`update private.provider_snapshot_storage_usage set ${column}=$1 where storage_class='history'`,[limit]);await assert.rejects(()=>scalar(db,'select private.provider_snapshot_complete($1,$2,$3,$4,$5)',[claim.jobId,claim.runId,claim.fence,saved.payload,saved.provenance]),/snapshot_artifact_capacity/);assert.equal(await scalar(db,'select snapshot_id::text from private.provider_snapshot_heads where job_id=$1',[id]),saved.id);await db.exec("update private.provider_snapshot_storage_usage set artifacts=10,stored_bytes=(select sum(stored_bytes)from private.provider_snapshot_artifacts),failed_jobs=500 where storage_class='history'");assert.equal(await scalar(db,"select private.provider_snapshot_fail($1,$2,$3,'compute_failed')",[claim.jobId,claim.runId,claim.fence]),true);await db.query("update private.provider_snapshot_jobs set status='ready',lease_until=null where id=$1",[id]);await db.exec("update private.provider_snapshot_storage_usage set failed_jobs=0 where storage_class='history'");}await checkCounters(db);}finally{await db.close()}});
